{"call": {"tool": "write_file", "arguments": {"path": "tests/test_round_corner_transparent_alpha.py", "content": "# -*- coding: utf-8 -*-\n\n# thumbor imaging service\n# https://github.com/thumbor/thumbor/wiki\n\n# Licensed under the MIT license:\n# http://www.opensource.org/licenses/mit-license\n# Copyright (c) 2011 globo.com thumbor@googlegroups.com\n\n\"\"\"Regression test for transparent round_corner carrying a dark ring.\n\nWhen round_corner runs with the transparent flag set, the antialiased\nedge of the arc used to keep its color channels and merely scale them\ntoward black by ``(1 - aa)``, while the alpha channel stayed fully\nopaque. That produces a dark outline along every curved corner.\n\nThe edge should instead keep its original color and become partly\ntransparent, so the picture fades into whatever is behind it.\n\"\"\"\n\nimport numpy as np\nfrom PIL import Image\nfrom tornado.testing import gen_test\n\nfrom tests.base import FilterTestCase\n\n\ndef _edge_pixels(image):\n    \"\"\"Return the RGBA values of pixels that lie on the arc edge.\n\n    A pixel is on the edge when its alpha is strictly between 0 and 255,\n    i.e. it was made partly transparent rather than fully filled or cut.\n    \"\"\"\n    data = np.array(image)\n    alpha = data[..., 3]\n    mask = (alpha > 0) & (alpha < 255)\n    return data[mask]\n\n\nclass RoundCornerTransparentAlphaTestCase(FilterTestCase):\n    @gen_test\n    async def test_transparent_corner_has_no_dark_ring(self):\n        image = await self.get_filtered(\n            \"source.jpg\",\n            \"thumbor.filters.round_corner\",\n            \"round_corner(50,255,255,255,1)\",\n            mode=\"RGBA\",\n        )\n\n        edges = _edge_pixels(image)\n\n        assert len(edges) > 0, (\n            \"the transparent round_corner produced no partly transparent \"\n            \"edge pixels, so the arc cannot fade into the background\"\n        )\n\n        # The edge must keep its color and fade through alpha, not move its\n        # colors toward black. Compare the edge colors with the opaque\n        # interior: scaled-to-black edge pixels are far darker than the\n        # pixels just inside the arc.\n        data = np.array(image)\n        interior = data[data[..., 3] == 255]\n        assert len(interior) > 0\n\n        edge_luma = edges[:, :3].mean()\n        interior_luma = interior[:, :3].mean()\n\n        assert edge_luma > interior_luma * 0.8, (\n            \"transparent round_corner edge pixels are scaled toward black \"\n            f\"(edge luma {edge_luma:.1f} vs interior luma \"\n            f\"{interior_luma:.1f}); the arc carries a dark ring\"\n        )\n\n    @gen_test\n    async def test_transparent_corner_pixels_are_partly_transparent(self):\n        image = await self.get_filtered(\n            \"source.jpg\",\n            \"thumbor.filters.round_corner\",\n            \"round_corner(50,255,255,255,1)\",\n            mode=\"RGBA\",\n        )\n\n        edges = _edge_pixels(image)\n\n        assert len(edges) > 0, (\n            \"no partly transparent pixels on the arc: the smoothing never \"\n            \"reaches the alpha channel\"\n        )\n\n        assert not np.all(edges[:, 3] == 255), (\n            \"edge pixels are fully opaque, so the corner is not smoothed \"\n            \"through the alpha channel\"\n        )\n"}}, "reply": {"content": [{"type": "text", "text": "write_file(tests/test_round_corner_transparent_alpha.py) wrote 3114 characters."}]}}
